const POLICE_FILING_ICON =
  'data:image/png;base64,';

type PoliceFilingIconProps = {
  className?: string;
  size?: number;
};

export function PoliceFilingIcon({
  className,
  size = 12,
}: PoliceFilingIconProps) {
  return (
    <img
      alt=""
      aria-hidden="true"
      className={className}
      decoding="async"
      height={size}
      src={POLICE_FILING_ICON}
      style={{ flex: 'none', objectFit: 'contain' }}
      width={size}
    />
  );
}
